import z3

def solve():
    n = 27
    E = [[z3.Bool(f"e_{i}_{j}") for j in range(n)] for i in range(n)]

    s = z3.Solver()

    # Undirected graph, no self loops
    for i in range(n):
        s.add(z3.Not(E[i][i]))
        for j in range(i + 1, n):
            s.add(E[i][j] == E[j][i])

    # Degree between 5 and 7
    for i in range(n):
        deg = z3.Sum([z3.If(E[i][j], 1, 0) for j in range(n)])
        s.add(deg >= 5)
        s.add(deg <= 7)

    # Girth >= 7 means no cycles of length 3, 4, 5, 6
    # No 3-cycles
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                s.add(z3.Not(z3.And(E[i][j], E[j][k], E[k][i])))

    # No 4-cycles
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                for l in range(k + 1, n):
                    # permutations of 4 vertices
                    # (i,j,k,l), (i,j,l,k), (i,k,j,l)
                    s.add(z3.Not(z3.And(E[i][j], E[j][k], E[k][l], E[l][i])))
                    s.add(z3.Not(z3.And(E[i][j], E[j][l], E[l][k], E[k][i])))
                    s.add(z3.Not(z3.And(E[i][k], E[k][j], E[j][l], E[l][i])))

    print(s.check())

solve()
